#!/usr/bin/env bash
# Reproduce S4 v2x-track submission 's4' (model-v2x-track/routed-g4): test-frame inference with the exact
# checkpoints, merge with the committed model.yaml, compare with the scored zip, repackage the same 50 frames, kit check.
# Generated by common/tools/reproduce_submission.py; scored zip model-v2x-track/routed-g4/submissions/2026-10-10_s4/v2x_s4_submission.zip (md5 29c8f7a9887d1443cd7f23289ecfc8b1).
# Usage: CUDA_VISIBLE_DEVICES=0 bash model-v2x-track/routed-g4/test/reproduce_s4.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
OUT=model-v2x-track/routed-g4/test/output/repro_s4
mkdir -p $OUT
# member cp4_tta: model-v2x-track/centerpoint-s4-g1v3, checkpoint md5 0440576e97aefb2bb0094f7f1a12bba4
python common/tools/pcdet_predict.py model-v2x-track/centerpoint-s4-g1v3 --ckpt model-v2x-track/centerpoint-s4-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/centerpoint-s4-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_cp4_tta.json
# member g1v2_tta: model-v2x-track/pointpillars-g1v2, checkpoint md5 7c3e9a1c074a67c58933791d2d2b2928
python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v2 --ckpt model-v2x-track/pointpillars-g1v2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pointpillars-g1v2/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_g1v2_tta.json
# member g1v3_tta: model-v2x-track/pointpillars-g1v3, checkpoint md5 b330667c29813de83e1f6a355775a83e
python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v3 --ckpt model-v2x-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pointpillars-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_g1v3_tta.json
# member pv_tta: model-v2x-track/pvrcnnpp-g1v3, checkpoint md5 d6018accd31346e39ca127d9bb923291
python common/tools/pcdet_predict.py model-v2x-track/pvrcnnpp-g1v3 --ckpt model-v2x-track/pvrcnnpp-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pvrcnnpp-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pv_tta.json
# member vr_tta: model-v2x-track/voxelrcnn-g1v3, checkpoint md5 22c3edbcdf927838cafe51bb261c50c6
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-g1v3 --ckpt model-v2x-track/voxelrcnn-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vr_tta.json
python common/tools/route_predictions.py merge model-v2x-track/routed-g4 --pred cp4_tta=$OUT/predictions_cp4_tta.json --pred g1v2_tta=$OUT/predictions_g1v2_tta.json --pred g1v3_tta=$OUT/predictions_g1v3_tta.json --pred pv_tta=$OUT/predictions_pv_tta.json --pred vr_tta=$OUT/predictions_vr_tta.json --out $OUT/predictions.json
python common/tools/reproduce_submission.py model-v2x-track/routed-g4 --tag s4 --compare $OUT/predictions.json
# the 50 realism frames: from the synthetic corpus when it is present (a check that it still gives the scored frames),
# else from the scored zip itself (a fresh clone has no corpus; the zip is in git)
if [ -d "$BDC_DATA/v2x-track/pcdet/g1-v3/points" ]; then SYN=(--syn-split val --syn-list model-v2x-track/routed-g4/submissions/2026-10-10_s4/synthetic_ids.txt); else SYN=(--syn-zip model-v2x-track/routed-g4/submissions/2026-10-10_s4/v2x_s4_submission.zip --syn-list model-v2x-track/routed-g4/submissions/2026-10-10_s4/synthetic_ids.txt); fi
python common/tools/package_submission.py model-v2x-track/routed-g4 --tag repro-s4 --pred $OUT/predictions.json --synthetic pcdet/g1-v3 "${SYN[@]}" --team ${BDC_TEAM:-KarmaRV} --ckpt 'reproduction of s4' --reproduction
Z=model-v2x-track/routed-g4/test/output/repro-s4/submission.zip
python common/tools/check_submission.py --track v2x $Z --official
python common/tools/reproduce_submission.py model-v2x-track/routed-g4 --tag s4 --compare-zip $Z     # predictions and frames against the scored zip
